head.b:skin:
/* --- RESET & DESIGN SYSTEM TOKENS --- */
:root {
    --bg-color: #030712;
    --bg-card: rgba(15, 23, 42, 0.75);
    --bg-card-hover: rgba(30, 41, 59, 0.85);
    --accent-cyan: #06b6d4;
    --accent-magenta: #ec4899;
    --accent-blue: #3b82f6;
    --accent-pink: #f43f5e;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --easy-bg: rgba(6, 182, 212, 0.1);
    --easy-border: rgba(6, 182, 212, 0.3);
    --nobel-bg: rgba(236, 72, 153, 0.1);
    --nobel-border: rgba(236, 72, 153, 0.3);
    --glass-border: rgba(255, 255, 255, 0.12);
    --radius-lg: 20px;
    --radius-md: 14px;
    --shadow-glow: 0 10px 40px -10px rgba(6, 182, 212, 0.3);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-main);
    font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    overflow-x: hidden;
    line-height: 1.6;
}

/* --- 3D CANVAS BACKGROUND --- */
#canvas-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 1;
    pointer-events: none;
}

/* --- LAYOUT OVERLAY --- */
.app-overlay {
    position: relative;
    z-index: 2;
    width: 100%;
    min-height: 100vh;
    padding: 2rem 1rem;
}

.main-container {
    max-width: 1300px;
    margin: 0 auto;
}

/* --- HEADER & UNDER CONSTRUCTION HERO --- */
.construction-header {
    text-align: center;
    margin-bottom: 3.5rem;
    padding: 2.5rem 1.5rem;
    background: rgba(15, 23, 42, 0.6);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    box-shadow: 0 20px 50px rgba(0,0,0,0.5);
}

.badge-construction {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 0.5rem 1.25rem;
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.2), rgba(245, 158, 11, 0.2));
    border: 1px solid rgba(245, 158, 11, 0.5);
    color: #fbbf24;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    border-radius: 9999px;
    margin-bottom: 1.25rem;
    animation: pulse-glow 2s infinite alternate;
}

@keyframes pulse-glow {
    0% { box-shadow: 0 0 10px rgba(245, 158, 11, 0.2); }
    100% { box-shadow: 0 0 25px rgba(245, 158, 11, 0.6); }
}

.construction-header h1 {
    font-size: clamp(1.8rem, 4vw, 3rem);
    font-weight: 800;
    background: linear-gradient(135deg, #ffffff 0%, #06b6d4 50%, #ec4899 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    margin-bottom: 0.75rem;
}

.construction-header .subtitle {
    font-size: 1.1rem;
    color: var(--accent-cyan);
    font-weight: 600;
    letter-spacing: 2px;
}

/* --- NAVBAR & BLOGGER HEADER WIDGET --- */
.nav-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    padding: 1rem 1.5rem;
    background: rgba(15, 23, 42, 0.7);
    backdrop-filter: blur(12px);
    border-radius: var(--radius-md);
    border: 1px solid var(--glass-border);
}

.nav-brand {
    font-weight: 800;
    font-size: 1.3rem;
    color: var(--text-main);
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 10px;
}

.nav-links {
    display: flex;
    gap: 1.5rem;
    list-style: none;
}

.nav-links a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--accent-cyan);
}

/* --- KNOWLEDGE GRID & BLOG CARDS --- */
.knowledge-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 2rem;
    margin-bottom: 3rem;
}

.card {
    background: var(--bg-card);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: 2rem;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

.card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-magenta));
    opacity: 0.6;
    transition: var(--transition);
}

.card:hover {
    transform: translateY(-8px);
    background: var(--bg-card-hover);
    border-color: rgba(6, 182, 212, 0.4);
    box-shadow: var(--shadow-glow);
}

.card:hover::before {
    opacity: 1;
}

.card-full {
    grid-column: 1 / -1;
}

.card .emoji {
    font-size: 2.5rem;
    margin-bottom: 1rem;
    display: inline-block;
}

.card h3 {
    font-size: 1.35rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 1.25rem;
    line-height: 1.4;
}

.card h3 a {
    color: inherit;
    text-decoration: none;
    transition: var(--transition);
}

.card h3 a:hover {
    color: var(--accent-cyan);
}

/* EASY SECTION (CHO TRẺ EM) */
.easy {
    background: var(--easy-bg);
    border-left: 4px solid var(--accent-cyan);
    border-radius: 0 var(--radius-md) var(--radius-md) 0;
    padding: 1.25rem;
    margin-bottom: 1.25rem;
    font-size: 0.98rem;
    color: #e2e8f0;
}

/* NOBEL SECTION (CHUYÊN GIA / NÂNG CAO) */
.nobel {
    background: var(--nobel-bg);
    border-left: 4px solid var(--accent-magenta);
    border-radius: 0 var(--radius-md) var(--radius-md) 0;
    padding: 1.25rem;
    font-size: 0.92rem;
    color: #cbd5e1;
}

.nobel ul {
    margin-left: 1.25rem;
    margin-top: 0.5rem;
}

.nobel li {
    margin-bottom: 0.5rem;
}

.highlight {
    color: var(--accent-cyan);
    font-weight: 600;
}

/* TAGS */
.tag-group {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 1.25rem;
}

.tag {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.15);
    padding: 0.3rem 0.75rem;
    border-radius: 9999px;
    font-size: 0.8rem;
    color: var(--accent-cyan);
    font-weight: 500;
}

/* BLOG PAGER / PAGINATION */
.blog-pager {
    display: flex;
    justify-content: space-between;
    margin: 2rem 0;
    padding: 1rem;
}

.blog-pager-newer-link, .blog-pager-older-link {
    padding: 0.75rem 1.5rem;
    background: rgba(15, 23, 42, 0.8);
    border: 1px solid var(--accent-cyan);
    color: var(--accent-cyan);
    border-radius: var(--radius-md);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.blog-pager-newer-link:hover, .blog-pager-older-link:hover {
    background: var(--accent-cyan);
    color: #000000;
}

/* FOOTER */
footer {
    text-align: center;
    padding: 3rem 1rem 1rem;
    color: var(--text-muted);
    font-size: 0.9rem;
    border-top: 1px solid var(--glass-border);
    margin-top: 4rem;
}

/* RESPONSIVE BREAKPOINTS */
@media (max-width: 768px) {
    .knowledge-grid {
        grid-template-columns: 1fr;
    }
    .nav-bar {
        flex-direction: column;
        gap: 1rem;
    }
    .card {
        padding: 1.5rem;
    }
}

body.script:
//
    import * as THREE from 'three';

    const container = document.getElementById('canvas-container');
    if (container) {
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x030712, 0.015);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 0, 45);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        container.appendChild(renderer.domElement);

        // Light sources
        const ambientLight = new THREE.AmbientLight(0x06b6d4, 1.2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xec4899, 2.5);
        dirLight.position.set(20, 20, 20);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x3b82f6, 3, 100);
        pointLight.position.set(-20, -10, 10);
        scene.add(pointLight);

        // 1. CYBER-HUMAN HEAD SILHOUETTE (Icosahedron / Head Form)
        const headGeo = new THREE.IcosahedronGeometry(12, 4);
        const headMat = new THREE.MeshStandardMaterial({
            color: 0x030712,
            wireframe: true,
            transparent: true,
            opacity: 0.25,
            roughness: 0.2,
            metalness: 0.8
        });
        const headMesh = new THREE.Mesh(headGeo, headMat);
        scene.add(headMesh);

        // 2. NEURAL NETWORK POINTS & SYNAPSES
        const particleCount = 700;
        const particleGeo = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const colors = new Float32Array(particleCount * 3);

        const colorCyan = new THREE.Color(0x06b6d4);
        const colorPink = new THREE.Color(0xec4899);

        for (let i = 0; i < particleCount; i++) {
            const u = Math.random();
            const v = Math.random();
            const theta = u * 2.0 * Math.PI;
            const phi = Math.acos(2.0 * v - 1.0);
            const r = 9 + Math.random() * 3;

            positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
            positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
            positions[i * 3 + 2] = r * Math.cos(phi);

            const mixedColor = colorCyan.clone().lerp(colorPink, Math.random());
            colors[i * 3] = mixedColor.r;
            colors[i * 3 + 1] = mixedColor.g;
            colors[i * 3 + 2] = mixedColor.b;
        }

        particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        particleGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const particleMat = new THREE.PointsMaterial({
            size: 0.6,
            vertexColors: true,
            transparent: true,
            opacity: 0.85,
            blending: THREE.AdditiveBlending
        });
        const particleSystem = new THREE.Points(particleGeo, particleMat);
        scene.add(particleSystem);

        // 3. INNER GLOWING BRAIN CORE
        const coreGeo = new THREE.SphereGeometry(5, 32, 32);
        const coreMat = new THREE.MeshBasicMaterial({
            color: 0x06b6d4,
            wireframe: true,
            transparent: true,
            opacity: 0.4
        });
        const coreMesh = new THREE.Mesh(coreGeo, coreMat);
        scene.add(coreMesh);

        // 4. HOLOGRAPHIC SCANNER RING
        const ringGeo = new THREE.TorusGeometry(15, 0.15, 16, 100);
        const ringMat = new THREE.MeshBasicMaterial({
            color: 0xec4899,
            transparent: true,
            opacity: 0.6
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI / 2;
        scene.add(ringMesh);

        // ANIMATION LOOP
        let clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const elapsedTime = clock.getElapsedTime();

            // Slow rotation
            headMesh.rotation.y = elapsedTime * 0.15;
            particleSystem.rotation.y = elapsedTime * 0.18;
            coreMesh.rotation.y = -elapsedTime * 0.25;
            coreMesh.rotation.x = elapsedTime * 0.1;

            // Pulsating core
            const scale = 1 + Math.sin(elapsedTime * 2) * 0.08;
            coreMesh.scale.set(scale, scale, scale);

            // Holographic Scanner movement
            ringMesh.position.y = Math.sin(elapsedTime * 1.5) * 10;

            renderer.render(scene, camera);
        }

        animate();

        // RESIZE HANDLER
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    }
//
